'use strict';
let chosenScenario='modern',difficulty=1,unitType=0,unitAmount=10,rankingTab='general',tutorialStep=0,currentDialog='',lastPause=false;
function openDialog(title,html,footer='',narrow=false){
 if(!$('#dialog-layer').innerHTML&&game&&mode==='play'){lastPause=game.paused;game.paused=true;}
 currentDialog=title;
 $('#dialog-layer').innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><h2>${title}</h2><button data-action="close" aria-label="${T('Kapat','Close')}">${icon('x')}</button></header><div class="modal-content">${html}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;
}
function closeDialog(){if(!$('#dialog-layer').innerHTML)return;$('#dialog-layer').innerHTML='';currentDialog='';if(mode==='play'&&game&&!game.won&&!game.loss)game.paused=lastPause;updateHUDValues();}
function backAction(){
 if($('#dialog-layer').innerHTML){closeDialog();return;}
 if(game?.targetMode){game.targetMode=null;dirty=true;toast(T('Hedef seçimi iptal edildi.','Target selection cancelled.'));return;}
 if(mode==='play'){showPause();return;}if(mode!=='menu'){showMenu();return;}
 openDialog(T('Oyundan çık','Exit game'),`<p>${T('Komuta merkezinden ayrılmak istiyor musun?','Leave the command center?')}</p>`,`<button data-action="close">${T('Vazgeç','Cancel')}</button><button class="primary" data-action="exit">${T('Çık','Exit')}</button>`,true);
}
function clearScreen(){
 $('#app').innerHTML='';$('#hud').innerHTML='';$('#country-panel').innerHTML='';$('#dialog-layer').innerHTML='';
 document.body.classList.toggle('play',mode==='play'||mode==='select');dirty=true;
}
function showRegistration(){
 mode='register';clearScreen();
 const opts=countries.slice().sort((a,b)=>cname(a).localeCompare(cname(b),lang)).map(c=>`<option value="${c.code}" ${c.code==='TR'?'selected':''}>${esc(cname(c))}</option>`).join('');
 $('#app').innerHTML=`<section class="setup-shell"><div class="setup-head"><div><div class="eyebrow">DICTATOR ERA</div><h2>${T('Bir dünya seni bekliyor.','A world awaits you.')}</h2></div><span class="badge">${T('İLK GİRİŞ','FIRST ENTRY')}</span></div><div class="setup-body"><div class="profile-form"><label for="language">${T('Dil','Language')}</label><select id="language"><option value="tr" ${lang==='tr'?'selected':''}>Türkçe</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><label for="home-country">${T('Profil ülkesi','Profile country')}</label><select id="home-country">${opts}</select><label for="player-name">${T('Komutan adı','Commander name')}</label><input id="player-name" maxlength="18" autocomplete="off" spellcheck="false" placeholder="${T('3–18 karakter','3–18 characters')}"><div class="form-error" id="name-error"></div><div class="stack"><button class="primary wide" data-action="guest">${icon('log-in')} ${T('Misafir olarak devam et','Continue as guest')}</button><button class="wide" data-action="google">${icon('globe')} ${T('Google Play ile giriş','Sign in with Google Play')}</button></div><div class="hint-box">${T('Misafir: tamamen çevrimdışı. Google Play: internetli hesap ve çevrimiçi sıralama için ayrılan giriş. Çok oyunculu: Yakında.','Guest: fully offline. Google Play: the sign-in route reserved for online identity and leaderboards. Multiplayer: Coming soon.')}</div><p class="fineprint">${T('Profil adı bu kurulumda bir kez belirlenir. Misafir adları yalnızca cihazında tutulur; küresel ad benzersizliği sunucu doğrulaması gerektirir. Kişisel veri veya konum toplanmaz.','Your name is set once per installation. Guest names stay on your device; global uniqueness requires server verification. No personal data or location is collected.')}</p><button class="ghost wide" data-action="licenses">${T('Lisanslar ve gizlilik','Licenses and privacy')}</button></div></div></section>`;
 $('.profile-form .stack').insertAdjacentHTML('afterbegin',`<button class="primary wide" data-action="online">${icon('globe')} ${T('Çevrimiçi hesap / giriş','Online account / sign-in')}</button>`);
 $('.profile-form .hint-box').textContent=T('Misafir: çevrimdışı. Online hesap: komutan adı ve şifreyle giriş, internetli sefer ve ortak sıralama. Google Play: ayrı kurulum gerekli. Çok oyunculu: Yakında.','Guest: offline. Online account: commander name/password, connected campaigns and shared rankings. Google Play: separate setup required. Multiplayer: Coming soon.');
}
function validateName(name){
 if(!/^[\p{L}\p{N}_ .-]{3,18}$/u.test(name))return T('3–18 karakter; harf, rakam, boşluk veya _ . - kullan.','Use 3–18 letters, numbers, spaces or _ . -');
 const normalized=name.toLocaleLowerCase('tr').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[01345@$]/g,c=>({'0':'o','1':'i','3':'e','4':'a','5':'s','@':'a','$':'s'}[c])).replace(/[^a-zı]/g,'');
 if(['fuck','shit','bitch','nigger','nazi','hitler','siktir','sikim','orospu','amk','pic','yarrak','gotveren'].some(w=>normalized.includes(w)))return T('Bu ad uygun değil. Başka bir ad seç.','This name is not allowed. Choose another.');
 return '';
}
function guestRegister(){
 const name=$('#player-name').value.trim().replace(/\s+/g,' '),error=validateName(name);if(error){$('#name-error').textContent=error;return;}
 profile={name,lang:$('#language').value,country:$('#home-country').value,mode:'guest',gold:0,victories:0,created:Date.now(),installation:window.Native?Native.installation():'local-session'};
 lang=profile.lang;store.write('profile',profile);sound();musicStart();showMenu();tutorialStep=0;showTutorial();
}
function showGoogle(){
 openDialog(T('Google Play bağlantısı','Google Play connection'),`<h3>${T('Online komutan hesabı hazır','Online commander accounts available')}</h3><p>${T('Bu itch.io sürümünde komutan adı ve şifreyle gerçek online giriş ve ortak sıralama vardır. Google Play Games hesabıyla giriş henüz yapılandırılmadı. Bu düğme Google kimliğini taklit etmez.','This itch.io build supports real online commander accounts and shared rankings using a name and password. Google Play Games sign-in is not configured. This button does not impersonate Google identity.')}</p>`,`<button class="primary" data-action="online">${T('Online girişe geç','Open online sign-in')}</button>`,true);
 return;
 /* Legacy explanation retained below for reference; not shown. */
 const online=window.Native?Native.online():navigator.onLine;
 openDialog(T('Google Play bağlantısı','Google Play connection'),`<div class="row">${icon(online?'wifi':'wifi-off')}<span>${online?T('İnternet bağlantısı var','Internet connection available'):T('İnternet bağlantısı yok','No internet connection')}</span></div><div class="rule"></div><h3>${T('Gerçek hesap, gerçek sıralama','Real identity, real ranking')}</h3><p>${T('Bu APK sürümünde Google Play Games projesi ve sıralama sunucusu yapılandırılmadı. Bu yüzden Google hesabı doğrulanamaz ve çevrimiçi puan gönderilemez. Misafir moduna gizlice çevrilmez veya sahte oyuncular gösterilmez.','The Google Play Games project and leaderboard server are not configured in this APK. Google identity cannot be verified and online scores cannot be submitted. This route will not silently turn into guest mode or show fake players.')}</p><div class="hint-box">${T('Yayıncı bağlantısı gerekli: Play Games uygulama kimliği, OAuth istemcisi, imza sertifikası ve doğrulama sunucusu. Bu bilgilerin sahibi tarafından bağlanması gerekir.','Publisher configuration is required: Play Games application ID, OAuth client, signing certificate and verification server. These must be connected by their owner.')}</div><p class="fineprint">${T('Misafir modu internet izni olsa bile ağ isteği yapmadan çalışır. Çevrimiçi sıralama için Google Play üzerinden doğrulanmış giriş zorunlu olacaktır.','Guest mode makes no network requests even though the app has network permission. Verified Google Play sign-in will be required for online rankings.')}</p>`,`<button class="primary" data-action="close">${T('Anladım','Understood')}</button>`,true);
}
function showMenu(){
 if(mode==='play'&&game)saveGame(true);mode='menu';selected=0;clearScreen();fitWorld();
 const c=countryByCode[profile?.country]||countryByCode.TR;
 $('#app').innerHTML=`<section class="menu"><header class="menu-top"><button class="profile" data-action="profile"><img class="round-flag" alt="" src="assets/flags/${c.flag}.svg"><span><strong>${esc(profile?.name||T('Komutan','Commander'))}</strong><small>${profile?.mode==='guest'?T('Misafir · Çevrimdışı','Guest · Offline'):T('Google Play · Çevrimiçi','Google Play · Online')}</small></span><span class="gold">${num(profile?.gold||0,0)}</span>${icon('coins')}</button><span class="badge">COMMANDER EDITION · 0.1</span></header><div class="menu-body"><div><div class="eyebrow">${T('DÜNYANIN KADERİ ELİNDE','THE WORLD IS YOURS TO SHAPE')}</div><h1 class="wordmark">DICTATOR<span>ERA</span></h1><p class="menu-tag">${T('Sınırları değil, tarihi değiştir.','Do not just redraw borders. Rewrite history.')}</p><nav class="menu-buttons"><button class="primary" data-action="scenarios"><span>${icon('play')} &nbsp;${T('Yeni sefer','New campaign')}</span>${icon('chevron-right')}</button><button data-action="resume" ${store.read('campaign')?'':'disabled'}><span>${icon('save')} &nbsp;${T('Sefere devam et','Continue campaign')}</span>${icon('chevron-right')}</button><button data-action="leaderboard"><span>${icon('trophy')} &nbsp;${T('Liderlik tablosu','Leaderboard')}</span>${icon('chevron-right')}</button><button data-action="multiplayer"><span>${icon('users')} &nbsp;${T('Çok oyunculu','Multiplayer')}</span><small>${T('YAKINDA','COMING SOON')}</small></button><button data-action="settings"><span>${icon('settings')} &nbsp;${T('Ayarlar','Settings')}</span>${icon('chevron-right')}</button><button data-action="tutorial"><span>${icon('book-open')} &nbsp;${T('Komutanın rehberi','Commander’s briefing')}</span>${icon('chevron-right')}</button></nav></div></div><div class="edition"><small>GRAND STRATEGY</small><strong>${T('Bir dünya. Sayısız ihtimal.','One world. Countless possibilities.')}</strong></div><footer class="menu-foot"><span>${T('ÖZGÜN BİR KÜRESEL STRATEJİ OYUNU','AN ORIGINAL GLOBAL STRATEGY GAME')}</span><button class="ghost" data-action="licenses" style="min-height:24px;padding:0;font-size:12px">${T('Lisanslar ve gizlilik','Licenses & privacy')}</button></footer></section>`;
 if(Online.isOnline())$('.profile small').textContent=T('Online hesap · Sunucu','Online account · Server');
 $('.menu-top .badge').textContent='COMMANDER EDITION · 0.2';
}
function showScenarios(){
 mode='scenarios';clearScreen();
 $('#app').innerHTML=`<section class="setup-shell"><header class="setup-head"><div><div class="eyebrow">${T('SEFER ARŞİVİ','CAMPAIGN ARCHIVE')}</div><h2>${T('Dönemini seç.','Choose your era.')}</h2></div><button data-action="menu">${icon('arrow-left')} ${T('Geri','Back')}</button></header><div class="setup-body"><div class="between" style="margin-bottom:16px"><p style="margin:0">${T('Altı başlangıç. Tek hedef: küresel hâkimiyet.','Six starting points. One objective: global domination.')}</p><select id="difficulty" style="width:160px"><option value=".75">${T('Rahat','Casual')}</option><option value="1" selected>${T('Dengeli','Balanced')}</option><option value="1.3">${T('Zorlu','Hard')}</option></select></div><div class="scenario-grid">${scenarios.map(s=>`<button class="scenario" data-action="choose-scenario" data-id="${s.id}"><img src="assets/${s.image}" alt=""><div class="scenario-content"><div class="eyebrow">${T(s.tagTR,s.tagEN)}</div><div class="year">${s.year}</div><h3>${T(s.tr,s.en)}</h3><p>${T(s.descTR,s.descEN)}</p><span class="gold">${T('Ülke seç','Select nation')} &nbsp; →</span></div></button>`).join('')}</div><p class="fineprint">${T('Senaryolar oyun dengesi için kurgulanmıştır. Ekonomik değerler simülasyon ölçeğindedir, güncel istatistik iddiası taşımaz. Harita, Natural Earth’ün kartografik sınırlarını temel alır; tartışmalı bölgelerde bir siyasi görüş ifade etmez.','Scenarios are fictionalized for game balance. Economic values are simulation-scaled, not live statistics. Natural Earth cartographic borders do not imply a political position on disputed territories.')}</p></div></section>`;
}
function chooseCountry(s){
 chosenScenario=s;mode='select';clearScreen();selected=countryByCode[profile.country]?.id||countryByCode.TR.id;focusCountry(selected);
 $('#app').innerHTML=`<aside class="selection-bar"><div class="between"><div class="eyebrow">${T('DÜNYA SENİ BEKLİYOR','THE WORLD AWAITS')}</div><button class="ghost" data-action="scenarios" style="min-height:28px;padding:3px">${icon('arrow-left')}</button></div><h2>${T('Ülkeni seç','Choose your nation')}</h2><small>${T('Haritaya dokun veya listeden ara.','Tap the map or search the list.')}</small><input id="country-search" placeholder="${T('Ülke ara…','Search nations…')}" autocomplete="off"><div class="country-list" id="country-results"></div><div id="selection-details"></div></aside><div class="map-controls"><button data-action="zoom-in" aria-label="${T('Yakınlaştır','Zoom in')}">${icon('plus')}</button><button data-action="zoom-out" aria-label="${T('Uzaklaştır','Zoom out')}">${icon('minus')}</button><button data-action="fit" aria-label="${T('Dünyayı göster','Show world')}">${icon('globe')}</button></div><div class="map-hint">${T('Sürükle: haritayı taşı · İki parmak: yakınlaştır','Drag to move · Pinch to zoom')}</div>`;
 filterCountries('');updateSelection();
}
function filterCountries(query){
 const q=query.toLocaleLowerCase(lang==='tr'?'tr':'en');
 const list=countries.filter(c=>c.cells>0&&(cname(c)+' '+c.code).toLocaleLowerCase(lang==='tr'?'tr':'en').includes(q)).sort((a,b)=>cname(a).localeCompare(cname(b),lang));
 $('#country-results').innerHTML=list.slice(0,60).map(c=>`<button data-action="select-nation" data-id="${c.id}">${flag(c)}<span>${esc(cname(c))}</span></button>`).join('')||`<div class="empty">${T('Sonuç yok.','No results.')}</div>`;
}
function updateSelection(){
 const c=byId(selected);if(!c)return;
 $('#selection-details').innerHTML=`<div class="selected-country"><img class="big-flag" alt="" src="assets/flags/${c.flag}.svg"><h3>${esc(cname(c))}</h3><small>${T('Başlangıç gücü','Starting power')} · ${T(scenerioName(chosenScenario).tr,scenerioName(chosenScenario).en)}</small><div class="selection-stats"><div class="mini-stat"><span>${T('Nüfus','Population')}</span><strong>${num(c.pop)}</strong></div><div class="mini-stat"><span>${T('Ekonomi endeksi','Economy index')}</span><strong>${num(c.baseGdp)}</strong></div></div><div class="hint-box">${T('Komşularını incele. Ordu ve bütçeni hazırlamadan savaşa girme.','Study your neighbors. Prepare your army and budget before going to war.')}</div><button class="primary wide" data-action="start" ${!c.cells?'disabled':''}>${T('Yönetimi devral','Take command')} &nbsp;→</button></div>`;
 $('.selection-bar > [data-action="start"]')?.remove();
 const start=$('#selection-details [data-action="start"]');
 if(start){start.style.marginTop='12px';$('.selection-bar').appendChild(start);}
 dirty=true;
}
function scenerioName(id){return scenarios.find(s=>s.id===id)||scenarios[0];}
function enterGameUI(){clearScreen();document.body.classList.add('play');updateHUD();drawCountryPanel();dirty=true;musicStart();}
function updateHUD(){
 if(!game||mode!=='play')return;const p=me();
 $('#hud').innerHTML=`<header class="topbar"><div class="nation-chip"><img class="round-flag" alt="" src="assets/flags/${p.flag}.svg"><div><strong>${esc(cname(p))}</strong><small>${esc(profile.name)}</small></div></div><nav class="hud-sections"><button class="hud-button" data-action="economy"><span class="line">${icon('coins')}<span id="hud-money"></span></span><span>${T('Bütçe','Budget')}</span></button><button class="hud-button" data-action="army"><span class="line">${icon('swords')}<span id="hud-army"></span></span><span>${T('Ordu','Army')}</span></button><button class="hud-button" data-action="technology"><span class="line">${icon('flask-conical')}<span id="hud-science"></span></span><span>${T('Teknoloji','Technology')}</span></button><button class="hud-button" data-action="ranking"><span class="line">${icon('chart-no-axes-combined')}<span id="hud-rank"></span></span><span>${T('Sıralama','Ranking')}</span></button><button class="hud-button" data-action="ideology"><span class="line">${icon('landmark')}<span id="hud-ideology">${T('Yönetim','Government')}</span></span><span>${T('İdeoloji','Ideology')}</span></button><button class="hud-button" data-action="diplomacy"><span class="line">${icon('handshake')}<span id="hud-allies"></span></span><span>${T('Diplomasi','Diplomacy')}</span></button></nav></header><button class="newsbar" data-action="newspaper"><b>${T('DÜNYA GAZETESİ','WORLD JOURNAL')}</b><span id="ticker"></span></button><div class="status-pill"><span>${T('Halk','Public')} <b id="hud-happy"></b></span><span>${T('Enflasyon','Inflation')} <b id="hud-inflation"></b></span><span class="gold" id="hud-progress"></span></div><div id="war-strips" class="war-strip"></div><div class="bottom-bar"><div class="clock"><button data-action="pause-toggle" id="pause-button" aria-label="${T('Duraklat / devam et','Pause / resume')}">${icon('pause')}</button><time id="date"></time>${[1,2,3].map(n=>`<button data-action="speed" data-value="${n}" id="speed-${n}">${n}×</button>`).join('')}</div><div class="toolbar"><button data-action="save" aria-label="${T('Kaydet','Save')}">${icon('save')}</button><button data-action="pause-menu" aria-label="${T('Menü','Menu')}">${icon('settings')}</button></div></div><div class="map-controls"><button data-action="zoom-in" aria-label="${T('Yakınlaştır','Zoom in')}">${icon('plus')}</button><button data-action="zoom-out" aria-label="${T('Uzaklaştır','Zoom out')}">${icon('minus')}</button><button data-action="focus" aria-label="${T('Ülkeme git','My nation')}">${icon('crosshair')}</button><button data-action="fit" aria-label="${T('Dünya','World')}">${icon('globe')}</button></div><div class="debug">FPS</div>`;
 updateHUDValues();updateTicker();
}
function generalScore(c){return c.land;}
function progressPercent(c){return c.land/landTotal*100;}
function updateHUDValues(){
 if(mode!=='play'||!game||!$('#hud-money'))return;const p=me();
 $('#hud-money').textContent=num(p.money);$('#hud-money').className=p.money<0?'red':'';
 $('#hud-army').textContent=num(totalUnits(p));$('#hud-science').textContent=Math.floor(p.research);
 const rank=countries.filter(c=>c.land).sort((a,b)=>generalScore(b)-generalScore(a)).findIndex(c=>c.id===p.id)+1;
 $('#hud-rank').textContent='#'+rank;$('#hud-allies').textContent=countries.filter(c=>c.land&&isAlly(p.id,c.id)).length;
 $('#hud-happy').textContent=Math.round(p.happiness)+'%';$('#hud-happy').className=p.happiness<40?'red':'green';
 $('#hud-inflation').textContent=p.inflation.toFixed(1)+'%';$('#hud-inflation').className=p.inflation>18?'red':'';
 $('#hud-progress').textContent=T('Hâkimiyet ','Dominance ')+progressPercent(p).toFixed(2)+'%';
 $('#date').textContent=dateText();$('#pause-button').innerHTML=icon(game.paused?'play':'pause');
 for(const n of [1,2,3])$('#speed-'+n)?.classList.toggle('active',game.speed===n&&!game.paused);
 $('#war-strips').innerHTML=game.wars.filter(w=>w.a===p.id||w.b===p.id).slice(0,4).map(w=>`<div class="war-item"><div class="between"><span>${flag(byId(w.a))} &nbsp; / &nbsp; ${flag(byId(w.b))}</span><span>${(w.taken/Math.max(1,w.initial)*100).toFixed(1)}%</span></div><div class="progress"><i style="width:${clamp(w.taken/Math.max(1,w.initial)*100,0,100)}%"></i></div><span>${w.landingTime>0?T('Deniz intikali sürüyor','Sea transit in progress'):T('Aktif cephe','Active front')} · ${w.support.filter(s=>s.power>0).length} ${T('destek','support')}</span></div>`).join('');
}
function updateTicker(){if($('#ticker'))$('#ticker').textContent=game?.news[0]?.title||T('Dünyadan gelişmeler','Developments around the world');}
function drawCountryPanel(){
 if(mode!=='play'||!selected||!game){$('#country-panel').innerHTML='';return;}const c=byId(selected),p=me();
 if(!c.land){$('#country-panel').innerHTML='';return;}
 const self=c.id===p.id,r=rel(p.id,c.id),war=game.wars.find(w=>(w.a===p.id&&w.b===c.id)||(w.b===p.id&&w.a===c.id));
 $('#country-panel').innerHTML=`<aside class="selected-info"><button class="close-country ghost" data-action="clear-selection" aria-label="${T('Kapat','Close')}">${icon('x')}</button><div class="row" style="margin-bottom:12px">${flag(c)}<h3 style="margin:0">${esc(cname(c))}</h3></div><div class="mini-stat"><span>${T('Ordu gücü','Military power')}</span><strong>${num(power(c))}</strong></div><div class="mini-stat"><span>${T('Ekonomi','Economy')}</span><strong>${num(c.gdp*1000000)}</strong></div><div class="mini-stat"><span>${T('Toprak payı','Territory share')}</span><strong>${progressPercent(c).toFixed(2)}%</strong></div>${!self?`<div class="mini-stat"><span>${T('İlişkiler','Relations')}</span><strong class="${r>=78?'green':r<25?'red':'gold'}">${Math.round(r)} / 100</strong></div>`:`<div class="mini-stat"><span>${T('Yönetim','Government')}</span><strong>${T(ide(c).tr,ide(c).en)}</strong></div>`}<div class="rule"></div><div class="actions">${self?`<button data-action="army">${icon('swords')} ${T('Ordu','Army')}</button><button data-action="economy">${icon('coins')} ${T('Bütçe','Budget')}</button>${p.units[5]>0?`<button data-action="air-target">${icon('plane')} ${T('Hava harekâtı','Air strike')}</button>`:''}${p.tech.includes('nuclear')?`<button class="danger" data-action="nuclear-target">${icon('radiation')} ${T('Nükleer','Nuclear')}</button>`:''}`:`<button data-action="country-diplomacy" data-id="${c.id}">${icon('handshake')} ${T('Diplomasi','Diplomacy')}</button>${war?`<button data-action="peace" data-id="${war.id}">${icon('shield')} ${T('Ateşkes','Ceasefire')}</button><button data-action="call-allies" data-id="${war.id}">${T('Savaş çağrısı','Call to war')}</button>`:`<button class="danger" data-action="war-confirm" data-id="${c.id}">${icon('swords')} ${T('Savaş ilanı','Declare war')}</button>`}${p.units[5]>0&&war?`<button data-action="air-country" data-id="${c.id}">${T('Hava saldırısı','Air strike')}</button>`:''}`}</div></aside>`;
}
function showArmy(){
 const p=me(),d=unitDefs[unitType],sc=scenerioName(game.scenario),cost=d.cost*unitAmount,locked=d.tech&&!p.tech.includes(d.tech);
 openDialog(T('Silahlı kuvvetler','Armed forces'),`<div class="between"><span class="muted">${T('Mevcut birlik','Current units')}: <strong class="gold">${num(totalUnits(p))}</strong></span><span class="muted">${T('Bakım / ay','Upkeep / month')}: ${num(upkeep(p))}</span></div><div class="unit-grid" style="margin-top:16px">${unitDefs.map((u,i)=>`<button class="unit-card ${i===unitType?'selected':''}" data-action="unit-type" data-id="${i}"><img src="assets/units-${sc.era}-${i}.webp" alt=""><div class="unit-caption"><strong>${T(u.tr,u.en)}</strong><small>${num(p.units[i],0)} ${T('birlik','units')} · ${num(u.cost)}</small></div></button>`).join('')}</div><div class="unit-details"><img src="assets/units-${sc.era}-${unitType}.webp" alt=""><div><h3>${T(d.tr,d.en)}</h3><p>${T(d.descTR,d.descEN)}</p><small>${T('Güç','Power')}: ${d.power} · ${T('Eğitim','Training')}: ${d.days} ${T('gün','days')} · ${T('Bakım','Upkeep')}: ${num(d.upkeep)} / ${T('ay','month')}</small></div></div>${locked?`<div class="hint-box">${icon('lock')} ${T('Önce ilgili teknoloji araştırılmalı.','Research the required technology first.')}</div>`:`<div class="between"><span>${T('Eğitilecek birlik','Units to train')}</span><strong class="gold" id="recruit-count">${unitAmount}</strong></div><input id="recruit-range" type="range" min="1" max="${Math.max(1,Math.min(1000,Math.floor(p.money/d.cost)))}" value="${unitAmount}" aria-label="${T('Birlik sayısı','Unit count')}"><div class="between" style="margin-top:12px"><small>${T('Toplam maliyet','Total cost')}: <b id="recruit-cost">${num(cost)}</b></small><button class="primary" data-action="recruit" ${p.money<cost?'disabled':''}>${T('Eğitimi başlat','Begin training')}</button></div>`}<div class="rule"></div><div class="eyebrow">${T('EĞİTİM KUYRUĞU','TRAINING QUEUE')}</div>${p.queue.length?p.queue.map(q=>`<div class="between"><span>${T(unitDefs[q.i].tr,unitDefs[q.i].en)} × ${q.n}</span><small>${Math.ceil(q.left)} ${T('gün','days')}</small></div><div class="progress"><i style="width:${(1-q.left/q.total)*100}%"></i></div>`).join(''):`<small>${T('Aktif eğitim emri yok.','No active training orders.')}</small>`}`);
}
function showEconomy(){
 const p=me();
 openDialog(T('Hazine ve bütçe','Treasury & budget'),`<div class="grid3"><div class="card"><small>${T('Hazine','Treasury')}</small><div class="stat">${num(p.money)}</div></div><div class="card"><small>${T('Aylık gelir','Monthly income')}</small><div class="stat green" id="budget-income"></div></div><div class="card"><small>${T('Aylık denge','Monthly balance')}</small><div class="stat" id="budget-net"></div></div></div><p>${T('Vergi gelir getirir; aşırı vergi halkı yorar. Sosyal bütçe istikrarı, bilim bütçesi araştırmayı destekler. Değişiklikler hemen uygulanır.','Taxes generate revenue, but excessive taxes strain the public. Social spending supports stability; science spending supports research. Changes apply immediately.')}</p>${[['tax',T('Vergiler','Tax rate'),10,55],['social',T('Sosyal bütçe','Social budget'),0,65],['science',T('Bilim bütçesi','Science budget'),0,55]].map(([k,l,min,max])=>`<label class="budget-row"><span>${l}</span><input type="range" min="${min}" max="${max}" value="${p[k]}" data-budget="${k}"><output id="budget-${k}">${p[k]}%</output></label>`).join('')}<div class="card"><div class="between"><span>${T('Askerî bakım','Military upkeep')}</span><strong>${num(upkeep(p))} / ${T('ay','month')}</strong></div><div class="between" style="margin-top:8px"><span>${T('Halk desteği','Public support')}</span><strong>${Math.round(p.happiness)}%</strong></div><div class="between" style="margin-top:8px"><span>${T('Enflasyon','Inflation')}</span><strong>${p.inflation.toFixed(1)}%</strong></div></div><div class="hint-box" id="budget-health"></div><small>${T('Zaman: 1× hızda bir ay yaklaşık 30 saniye; 3× hızda 10 saniye. Menü açıkken sefer duraklar.','Time: one month takes about 30 seconds at 1×, or 10 seconds at 3×. Campaign pauses while a panel is open.')}</small>`);
 updateBudget();
}
function updateBudget(){
 const p=me(),b=budget(p);$('#budget-income').textContent=num(b.income);$('#budget-net').textContent=(b.net>=0?'+':'')+num(b.net);
 $('#budget-net').className='stat '+(b.net<0?'red':b.net<b.income*.12?'gold':'green');
 const health=$('#budget-health'),good=b.net>=0&&p.tax<=36&&p.social>=18;
 health.className='hint-box '+(good?'green':b.net<0?'red':'gold');
 health.textContent=good?T('Dengeli bütçe. Gelir, istikrar ve araştırma birlikte ilerliyor.','Balanced budget. Revenue, stability and research work together.'):b.net<0?T('Bütçe açığı. Hazinen tükenirse enflasyon ve ordu kayıpları artar.','Budget deficit. An empty treasury increases inflation and army attrition.'):T('Gelir pozitif; ancak yüksek vergi veya düşük sosyal harcama halk desteğini azaltabilir.','Revenue is positive, but high taxes or low social spending can erode public support.');
 updateHUDValues();
}
function showTechnology(){
 const p=me();
 openDialog(T('Teknoloji ağacı','Technology tree'),`<div class="between"><span>${T('Araştırma puanı','Research points')}: <strong class="gold">${Math.floor(p.research)}</strong></span><small>${T('Her ay bilim bütçesinden üretilir.','Generated monthly by your science budget.')}</small></div>${p.currentResearch?`<div class="hint-box">${T('Devam ediyor','In progress')}: ${T(techDefs.find(t=>t.id===p.currentResearch.id).tr,techDefs.find(t=>t.id===p.currentResearch.id).en)} · ${p.currentResearch.left} ${T('ay','months')}<div class="progress"><i style="width:${(1-p.currentResearch.left/p.currentResearch.total)*100}%"></i></div></div>`:''}<div class="tech-grid" style="margin-top:16px">${techDefs.map(t=>{const done=p.tech.includes(t.id),active=p.currentResearch?.id===t.id,req=t.req.every(r=>p.tech.includes(r));return `<div class="tech-card ${done?'unlocked':active?'researching':''}"><div class="row">${icon(t.id==='nuclear'?'radiation':t.id==='air'?'plane':t.id==='industry'?'coins':t.id==='naval'?'globe':'flask-conical')}<h3 style="margin:0">${T(t.tr,t.en)}</h3></div><p>${T(t.descTR,t.descEN)}</p><small>${t.cost} ${T('puan','points')} · ${t.time} ${T('ay','months')}</small>${t.req.length?`<div class="fineprint" style="margin-top:5px">${T('Ön koşul','Requires')}: ${t.req.map(id=>{const r=techDefs.find(t=>t.id===id);return T(r.tr,r.en);}).join(' + ')}</div>`:''}<button style="margin-top:12px" data-action="research" data-id="${t.id}" ${done||p.currentResearch||!req||p.research<t.cost?'disabled':''}>${done?T('Tamamlandı','Completed'):active?T('Araştırılıyor','Researching'):!req?T('Ön koşul kilitli','Prerequisite locked'):T('Araştır','Research')}</button></div>`;}).join('')}</div>`);
}
function showIdeologies(){
 const p=me();openDialog(T('İdeoloji ve yönetim','Ideology & government'),`<p>${T('Her yönetim yaklaşımının gücü ve bedeli vardır. Reform, 8 puan halk desteğine mal olur; tekrar değiştirmek için 12 ay geçmelidir.','Each approach has strengths and costs. Reform costs 8 public-support points, and requires a 12-month wait between changes.')}</p><div class="grid2">${ideologies.map(i=>`<button class="ideology-card ${p.ideology===i.id?'selected':''}" data-action="ideology-detail" data-id="${i.id}"><div class="row">${icon(i.icon)}<h3 style="margin:0">${T(i.tr,i.en)}</h3></div><small>${T('Gelir','Income')} ${Math.round((i.income-1)*100)}% · ${T('Ordu','Army')} ${Math.round((i.military-1)*100)}% · ${T('Bilim','Science')} ${Math.round((i.research-1)*100)}%</small>${p.ideology===i.id?`<span class="badge" style="margin-top:8px">${T('AKTİF YÖNETİM','CURRENT GOVERNMENT')}</span>`:''}</button>`).join('')}</div>`);
}
function showIdeologyDetail(id){
 const i=ideologies.find(i=>i.id===id),p=me();openDialog(T(i.tr,i.en),`<div class="ideology-emblem">${icon(i.icon)}</div><p>${T(i.descTR,i.descEN)}</p><div class="grid3"><div class="card"><small>${T('Gelir','Income')}</small><div class="stat">${i.income>=1?'+':''}${Math.round((i.income-1)*100)}%</div></div><div class="card"><small>${T('Askerî güç','Military')}</small><div class="stat">${i.military>=1?'+':''}${Math.round((i.military-1)*100)}%</div></div><div class="card"><small>${T('Araştırma','Research')}</small><div class="stat">${i.research>=1?'+':''}${Math.round((i.research-1)*100)}%</div></div></div><div class="hint-box">${T('Halk memnuniyeti aylık etkisi','Monthly public satisfaction effect')}: ${i.happy>=0?'+':''}${i.happy.toFixed(2)}. ${T('Bu değer oyun dengesi içindir; gerçek siyasi ideolojiler hakkında bilimsel bir değerlendirme değildir.','These are game-balance values, not scientific claims about real political ideologies.')}</div>`,`<button data-action="ideology">${T('Geri','Back')}</button><button class="primary" data-action="reform" data-id="${id}" ${p.ideology===id||game.monthCount-p.lastReform<12?'disabled':''}>${T('Bu yönetimi benimse','Adopt this government')}</button>`);
}
function rankingValue(c,tab){return tab==='military'?power(c):tab==='economy'?c.gdp*1e6:c.land;}
function showRanking(tab=rankingTab){
 rankingTab=tab;const sorted=countries.filter(c=>c.land>0).sort((a,b)=>rankingValue(b,tab)-rankingValue(a,tab));
 openDialog(T('Dünya güç dengesi','World balance of power'),`<div class="tabs">${[['general',T('Genel','General')],['economy',T('Ekonomi','Economy')],['military',T('Askerî','Military')]].map(([k,l])=>`<button class="${k===tab?'active':''}" data-action="rank-tab" data-id="${k}">${l}</button>`).join('')}</div><div class="hint-box">${tab==='general'?T('Genel sıralama = kontrol edilen dünya toprağı. %100 hâkimiyete ulaşınca zafer kazanırsın ve bir kez 50 yerel altın alırsın.','General ranking = controlled world territory. Reach 100% dominance to win and receive 50 local gold once.'):T('Değerler bu seferin simülasyonuna aittir.','Values belong to this campaign simulation.')}</div>${sorted.map((c,i)=>`<div class="ranking-row ${c.id===game.player?'me':''}"><span>${i+1}</span>${flag(c)}<span>${esc(cname(c))}</span><span>${tab==='general'?progressPercent(c).toFixed(2)+'%':num(rankingValue(c,tab))}</span></div>`).join('')}`);
}
function showLeaderboard(){
 if(Online.isOnline())return Online.leaderboard();
 openDialog(T('Liderlik tablosu','Leaderboard'),`<div class="empty">${icon('trophy')}<h3>${T('Misafir modu çevrimdışıdır.','Guest mode is offline.')}</h3><p>${T('Ortak sıralama için online komutan hesabınla giriş yap. Misafir zaferi ve altını yalnızca cihazda kalır. Çok oyunculu henüz açık değildir.','Sign in to an online commander account for shared rankings. Guest wins and gold stay on your device. Multiplayer is not available yet.')}</p></div><div class="card between"><span>${T('Yerel zafer','Local victories')}: ${profile.victories||0}</span><span class="gold">${icon('coins')} ${profile.gold||0}</span></div>`,`<button class="primary" data-action="online">${T('Online hesap / giriş','Online account / sign-in')}</button>`,true);
}
function showDiplomacy(target){
 if(target){showCountryDiplomacy(Number(target));return;}
 const allies=countries.filter(c=>c.land&&isAlly(game.player,c.id)),neighbors=neighborsOf(game.player).map(byId);
 openDialog(T('Diplomasi merkezi','Diplomacy center'),`<div class="grid2"><div class="card"><small>${T('Müttefikler','Allies')}</small><div class="stat">${allies.length}</div></div><div class="card"><small>${T('Ticaret anlaşmaları','Trade agreements')}</small><div class="stat">${me().trade.length}</div></div></div><div class="hint-box">${T('İttifak savaşa otomatik katılım değildir. Savaş açtıktan sonra Savaş Çağrısı ile belirli bir müttefikten asker, para veya ikmal iste. Kara sınırı olmayan müttefik kendi adına toprak alamaz.','An alliance does not mean automatic war entry. After declaring war, use Call to War to request troops, money or supplies from a specific ally. An ally without a shared land border cannot annex land on its own.')}</div><h3>${T('Müttefiklerin','Your allies')}</h3><div class="grid3">${allies.map(c=>`<button data-action="country-diplomacy" data-id="${c.id}">${flag(c)} ${esc(cname(c))}</button>`).join('')||`<small>${T('Henüz müttefik yok.','No allies yet.')}</small>`}</div><div class="rule"></div><h3>${T('Sınır komşuları','Land neighbors')}</h3><div class="grid3">${neighbors.map(c=>`<button data-action="country-diplomacy" data-id="${c.id}">${flag(c)} ${esc(cname(c))}<small style="display:block">${Math.round(rel(game.player,c.id))}/100</small></button>`).join('')||`<small>${T('Kara komşusu yok.','No land neighbors.')}</small>`}</div>`);
}
function showCountryDiplomacy(id){
 const c=byId(id),p=me(),r=rel(p.id,id),war=game.wars.find(w=>(w.a===p.id&&w.b===id)||(w.a===id&&w.b===p.id));
 selected=id;dirty=true;
 openDialog(T('Diplomatik dosya','Diplomatic dossier'),`<div class="row"><img src="assets/portraits-${Math.abs(id)%6}.webp" alt="${T('Kurgusal devlet temsilcisi','Fictional state representative')}" style="width:110px;height:120px;object-fit:cover;border:1px solid #52616a"><div>${flag(c)}<h3 style="margin:10px 0">${esc(cname(c))}</h3><div class="diplomacy-score">${Math.round(r)} <small>/ 100</small></div><small>${T('Kurgusal temsilci portresi','Fictional representative portrait')}</small></div></div><div class="progress"><i style="width:${r}%;background:${r>=78?'var(--green)':r<25?'var(--red)':'var(--gold)'}"></i></div><div class="grid2" style="margin-top:20px">${[['improve','handshake',T('İlişkileri geliştir','Improve relations')],['aid','coins',T('Ekonomik yardım','Economic aid')],[isAlly(p.id,id)?'break':'alliance','shield',isAlly(p.id,id)?T('İttifakı sonlandır','End alliance'):T('İttifak öner','Propose alliance')],['trade','globe',T('Ticaret anlaşması','Trade agreement')],['propaganda','newspaper',T('Diplomatik kınama','Diplomatic condemnation')]].map(([a,i,l])=>`<button data-action="dip-action" data-id="${id}" data-kind="${a}" ${war&&a!=='propaganda'?'disabled':''}>${icon(i)} ${l}</button>`).join('')}${war?`<button data-action="peace" data-id="${war.id}">${icon('shield')} ${T('Ateşkes iste','Request ceasefire')}</button>`:`<button class="danger" data-action="war-confirm" data-id="${id}">${icon('swords')} ${T('Savaş ilan et','Declare war')}</button>`}</div><div class="hint-box">${T('Yardım ve diplomasi bütçe kullanır. İttifak için güçlü ilişkiler gerekir. Bir ülkeyi kınamak, o ülkenin rakipleriyle ilişkini iyileştirebilir.','Aid and diplomacy use treasury funds. Alliances require strong relations. Condemning a nation can improve relations with its rivals.')}</div>`);
}
function showWarConfirm(id){
 const c=byId(id),p=me(),border=frontier(p.id,id).length>0;
 openDialog(T('Savaş ilanı','Declaration of war'),`<div class="row">${flag(p)} ${icon('swords')} ${flag(c)}</div><h3 style="margin-top:16px">${esc(cname(c))}</h3><p>${T('Müttefikler otomatik olarak savaşa girmez. Çatışma yalnızca ortak sınırdan ilerler. Müttefik desteğini savaş ilanından sonra ayrıca çağırabilirsin.','Allies do not enter automatically. Land combat advances from a shared border. You can request allied support after declaring war.')}</p><div class="grid2"><div class="card"><small>${T('Senin gücün','Your power')}</small><div class="stat">${num(power(p))}</div></div><div class="card"><small>${T('Hedef gücü','Target power')}</small><div class="stat">${num(power(c))}</div></div></div><div class="hint-box">${border?T('Ortak kara sınırı var. Kara harekâtı mümkün.','Shared land border. Ground offensive available.'):p.tech.includes('naval')?T('Kara sınırı yok. 12 Mn maliyetle ulaşılabilir kıyıya deniz çıkarması planlanacak.','No land border. A landing on a reachable coast costs 12 M.'):T('Ortak kara sınırı yok. Önce Denizaşırı Lojistik araştırılmalı.','No shared border. Research Overseas Logistics first.')}</div>`,`<button data-action="close">${T('Vazgeç','Cancel')}</button><button class="danger" data-action="declare" data-id="${id}" ${isAlly(p.id,id)||!border&&!p.tech.includes('naval')?'disabled':''}>${T('Savaş ilan et','Declare war')}</button>`,true);
}
function showCallAllies(wid){
 const w=game.wars.find(w=>w.id===Number(wid));if(!w)return;const allies=countries.filter(c=>c.land&&isAlly(game.player,c.id)&&c.id!==w.b);
 openDialog(T('Savaş çağrısı','Call to war'),`<p>${T('Her müttefik çağrıyı kendi ilişkileri ve yıpranmasına göre değerlendirir. Destek bayrakları senin cephende görünür; toprak senin adına ilerler.','Each ally evaluates the request using its relationships and exhaustion. Supporting flags appear on your front; territory advances in your name.')}</p>${allies.length?allies.map(c=>{let used=w.support.find(s=>s.id===c.id);let border=frontier(c.id,w.b).length>0;return `<div class="card" style="margin-top:12px"><div class="between"><span>${flag(c)} ${esc(cname(c))}</span><small>${Math.round(rel(game.player,c.id))}/100</small></div>${used?`<div class="hint-box">${used.type==='declined'?T('Bu çağrı reddedildi.','This call was declined.'):T('Bu cepheye destek verildi.','Support assigned to this front.')}</div>`:`<div class="grid2" style="margin-top:12px">${[['troops',T('Piyade desteği','Troop support')],['money',T('Mali destek','Financial aid')],['supply',T('İkmal desteği','Supply support')],...(border?[['front',T('Kendi cephesini aç','Open own front')]]:[])].map(([type,text])=>`<button data-action="ally-request" data-id="${c.id}" data-war="${w.id}" data-kind="${type}">${text}</button>`).join('')}</div>`}</div>`;}).join(''):`<div class="empty">${T('Çağrılabilecek müttefikin yok.','No allies available to call.')}</div>`}`);
}
function eventNotification(type){toast(T('Dünya Gazetesi: yeni gelişme.','World Journal: a new development.'));sound('click');}
function showNewspaper(){
 const image={war:0,diplomacy:5,protest:3,flood:1,quake:2,nuclear:2};
 openDialog(T('Dünya Gazetesi','World Journal'),`<div class="eyebrow">${T('DOĞRUDAN CEPHEDEN VE BAŞKENTLERDEN','FROM THE FRONTS AND CAPITALS')}</div>${game.news.map(n=>`<article class="news-item"><img src="assets/events-${image[n.type]??4}.webp" alt=""><div><small>${esc(n.date)}</small><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div></article>`).join('')}`);
}
function showTutorial(){
 const steps=[
 [T('Hoş geldin, komutan.','Welcome, Commander.'),T('Bu bir harita boyama yarışı değil. Güçlü bir ekonomi kur, komşularını incele ve doğru zamanda harekete geç. Altı üst menü ihtiyacın olan her şeyi toplar.','This is not a race to paint a map. Build an economy, study your neighbors and act at the right moment. The six top sections contain everything you need.')],
 [T('Önce bütçe, sonra ordu.','Budget first, army second.'),T('Bütçe simgesinden vergileri, sosyal desteği ve bilimi ayarla. Yeşil denge güvenlidir. Ordu bölümünde altı birlik tipinden birini seçip eğitim emri ver.','Use Budget to adjust taxes, social support and science. Green means balanced. In Army, choose one of six unit types and issue a training order.')],
 [T('Sınırlar önemlidir.','Borders matter.'),T('Haritadan bir komşu seç. Savaş ilanından sonra cephen adım adım ilerler. Sınırı olmayan bir müttefik ülkene uzaktan destek verir; kendi başına gelip toprak alamaz.','Select a neighboring nation on the map. After a declaration, the front advances progressively. An ally without a border can support you but cannot annex land on its own.')],
 [T('Dünyayı dinle.','Listen to the world.'),T('Gazete gelişmeleri üstte toplar. Krizler durduk yere her saniye gelmez; uzun ekonomik sorunlar protestoya neden olur. İttifaklar otomatik savaş değildir, destek için Savaş Çağrısı kullan.','The journal gathers developments at the top. Crises do not appear every second; prolonged economic problems cause protests. Alliances are not automatic wars: use Call to War to request support.')],
 [T('Tarihi sen yaz.','Write your own history.'),T('Teknolojiyi geliştir, yönetim biçimini belirle ve dünyadaki payını büyüt. Genel sıralamada %100 hâkimiyet zafere ulaşır. Hız en fazla 3×; açık menülerde zaman durur.','Advance technology, choose your government and grow your world share. Reach 100% in General ranking to win. Speed is limited to 3×; time stops while panels are open.')]
 ];
 const s=steps[tutorialStep];openDialog(T('Komutanın rehberi','Commander’s briefing'),`<div class="tutorial"><img src="assets/portraits-0.webp" alt="${T('Kurgusal komutan','Fictional commander')}"><div><div class="eyebrow">${T('KOMUTA BRİFİNGİ','COMMAND BRIEFING')} · ${tutorialStep+1} / ${steps.length}</div><h3>${s[0]}</h3><p>${s[1]}</p><div class="tutorial-step">${icon(['globe','coins','swords','newspaper','trophy'][tutorialStep])} ${T('Sade komuta. Derin strateji.','Simple command. Deep strategy.')}</div></div></div>`,`<button data-action="close">${T('Kapat','Close')}</button>${tutorialStep>0?`<button data-action="tutorial-prev">${T('Geri','Back')}</button>`:''}<button class="primary" data-action="${tutorialStep===4?'close':'tutorial-next'}">${tutorialStep===4?T('Hazırım','Ready'):T('Devam','Continue')}</button>`);
}
function showSettings(){
 openDialog(T('Ayarlar','Settings'),`<div class="checkrow"><span>${T('Dil','Language')}</span><select id="settings-language" style="width:160px"><option value="tr" ${lang==='tr'?'selected':''}>Türkçe</option><option value="en" ${lang==='en'?'selected':''}>English</option></select></div><label class="checkrow"><span>${T('Müzik','Music')}</span><input class="setting-range" type="range" min="0" max="1" step=".05" value="${settings.music}" data-setting="music"></label><label class="checkrow"><span>${T('Ses efektleri','Sound effects')}</span><input class="setting-range" type="range" min="0" max="1" step=".05" value="${settings.sfx}" data-setting="sfx"></label>${[['flags',T('Topraklarda bayrak dokusu','Flag overlays')],['admin',T('İnce idari sınırlar','Subtle administrative boundaries')],['labels',T('Harita isimleri','Map labels')],['haptics',T('Dokunsal geri bildirim','Haptic feedback')]].map(([k,l])=>`<label class="checkrow"><span>${l}</span><input type="checkbox" data-setting="${k}" ${settings[k]?'checked':''}></label>`).join('')}<div class="checkrow"><span>${T('Görüntü çözünürlüğü','Render resolution')}</span><select id="quality" style="width:160px"><option value="1" ${settings.quality===1?'selected':''}>${T('Dengeli','Balanced')}</option><option value="2" ${settings.quality===2?'selected':''}>${T('Yüksek','High')}</option></select></div><p class="fineprint">${T('Olaylar kapatılamaz. Krizler ekonomik koşullara ve uzun aralıklara bağlıdır. Kare hızı cihazın ekranı ve donanımıyla sınırlıdır; 120 FPS garantisi verilmez.','Events cannot be disabled. Crises depend on economic conditions and long intervals. Frame rate is limited by device hardware and refresh rate; 120 FPS is not guaranteed.')}</p>`);
}
function showProfile(){
 if(Online.isOnline())return Online.showProfile();
 const c=countryByCode[profile.country];openDialog(T('Komutan profili','Commander profile'),`<div class="row">${flag(c)}<h3>${esc(profile.name)}</h3></div><p>${T('Profil adı bu kurulumda sabittir. Misafir kaydı çevrimdışı tutulur; yeniden kurulum veya uygulama verilerinin silinmesi cihaz kısıtını aşabilir.','The profile name is fixed for this installation. Guest identity is offline; reinstalling or clearing app data can reset the installation limit.')}</p><div class="grid2"><div class="card"><small>${T('Yerel altın','Local gold')}</small><div class="stat gold">${profile.gold||0}</div></div><div class="card"><small>${T('Zafer','Victories')}</small><div class="stat">${profile.victories||0}</div></div></div><div class="hint-box">${T('Altın yalnızca zafer puanıdır. Satın alma, asker güçlendirme veya ekonomi avantajı sağlamaz. Misafir puanları çevrimiçi sıralama sayılmaz.','Gold is a victory score only. It cannot buy units, upgrades or economic advantages. Guest scores are not online rankings.')}</div>`,`<button data-action="google">${T('Google Play bağlantısı','Google Play connection')}</button>`,true);
 Online.guestLeaderboardButton();
}
function showPause(){
 if(!game)return;game.paused=true;lastPause=true;
 openDialog(T('Komuta menüsü','Command menu'),`<div class="stack"><button class="primary wide" data-action="continue">${icon('play')} ${T('Sefere dön','Return to campaign')}</button><button class="wide" data-action="save">${icon('save')} ${T('Oyunu kaydet','Save campaign')}</button><button class="wide" data-action="settings">${icon('settings')} ${T('Ayarlar','Settings')}</button><button class="wide" data-action="tutorial">${icon('book-open')} ${T('Rehber','Briefing')}</button><button class="wide" data-action="menu">${icon('house')} ${T('Kaydet ve ana menüye dön','Save and return to menu')}</button></div>`, '',true);
}
function showVictory(){
 openDialog(T('Dünya senin.','The world is yours.'),`<div class="victory"><div class="sigil">D<span>E</span></div><div class="eyebrow" style="margin-top:28px">${T('KÜRESEL HÂKİMİYET','GLOBAL DOMINATION')}</div><h2>${T('ZAFER','VICTORY')}</h2><p>${esc(cname(me()))} · 100%</p><div class="medal">+50 ${T('ALTIN','GOLD')}</div><small>${T('Yerel zafer puanı profiline işlendi.','Local victory score added to your profile.')}</small></div>`,`<button class="primary" data-action="menu">${T('Ana menü','Main menu')}</button>`);
 if(Online.isOnline()){
  $('.victory small').textContent=game.online?.accepted?T('Sunucu zaferini kabul etti. Online puanın güncellendi.','The server accepted your victory. Your online score was updated.'):T('Online zafer sunucu onayını bekliyor. Henüz altın eklenmedi.','Online victory awaits server approval. No gold has been added yet.');
  $('.victory .medal').textContent=game.online?.accepted?'+50 '+T('ONLINE ALTIN','ONLINE GOLD'):T('ONAY BEKLİYOR','PENDING APPROVAL');
  if(!game.online?.accepted)$('.modal-footer').insertAdjacentHTML('afterbegin',`<button data-online="finish">${T('Zaferi sunucuya gönder','Submit victory')}</button>`);
 }
}
function showDefeat(){
 openDialog(T('Bir dönemin sonu','The end of an era'),`<img class="event-art" src="assets/events-0.webp" alt=""><p>${T('Ülkenin son toprakları da el değiştirdi. Bir sonraki seferde bütçeni, savunmanı ve müttefiklerini daha dikkatli dengele.','Your last territory has fallen. In your next campaign, balance the treasury, defense and allies more carefully.')}</p>`,`<button class="primary" data-action="menu">${T('Ana menü','Main menu')}</button>`,true);
}
function confirmNuclear(target,city){
 openDialog(T('Stratejik saldırıyı doğrula','Confirm strategic strike'),`<h3>${esc(city.name)}, ${esc(cname(byId(target)))}</h3><p>${T('Bu saldırı ağır sivil ve askerî kayıplara, ekonomik yıkıma ve uluslararası ilişkilerde büyük düşüşe neden olur. Maliyet: 50 Mn.','This strike causes severe civilian and military losses, economic devastation and a major collapse in international relations. Cost: 50 M.')}</p>`,`<button data-action="cancel-target">${T('Vazgeç','Cancel')}</button><button class="danger" data-action="nuclear-launch" data-id="${target}" data-x="${city.xy[0]}" data-y="${city.xy[1]}">${T('Saldırıyı başlat','Launch strike')}</button>`,true);
}
function showLicenses(){
 openDialog(T('Lisanslar ve gizlilik','Licenses & privacy'),`<h3>Dictator Era · 0.1.0</h3><p>${T('Bağımsız ve özgün bir strateji oyunu. Dummynation, Age of History veya Rule the World ile bağlantılı değildir. Bu oyunların kodu, logosu veya sanat varlıkları kullanılmamıştır.','An independent, original strategy game. Not affiliated with Dummynation, Age of History or Rule the World. Their code, logos and artwork are not used.')}</p><h3>${T('Veri ve varlıklar','Data & assets')}</h3><p class="fineprint">Natural Earth: public-domain country, admin-1, city and shaded-relief data.<br>https://www.naturalearthdata.com/about/terms-of-use/<br>D3: ISC. https://github.com/d3/d3/blob/main/LICENSE<br>Lucide: ISC. https://lucide.dev/license<br>Country Flag Icons: MIT. https://github.com/catamphetamine/country-flag-icons<br>Barlow & Cinzel: SIL Open Font License 1.1. https://fonts.google.com<br>${T('Arka planlar, birlik ve temsilci resimleri bu proje için yapay zekâyla üretildi. Portreler kurgusaldır; güncel devlet başkanları değildir. Müzik ve efektler bu proje için sentezlendi.','Backgrounds, unit and representative images are AI-generated for this project. Portraits are fictional, not current heads of state. Music and sound effects are synthesized for this project.')}</p><h3>${T('Gizlilik','Privacy')}</h3><p class="fineprint">${T('Misafir modunda kişisel veri gönderilmez, izleme, reklam veya analitik SDK bulunmaz. Profil ve oyun kaydı uygulamanın özel depolamasında tutulur. Yerel kurulum kimliği cihazın donanım kimliği değildir. İnternet izni çevrimiçi hizmet altyapısı için ayrılmıştır; bu sürümde Google Play girişi ve sunucu sıralaması bağlı değildir.','Guest mode transmits no personal data and includes no tracking, advertising or analytics SDK. Profile and saves stay in private app storage. Installation identity is not a hardware identifier. Network permission is reserved for online services; this version has no connected Google Play login or authoritative leaderboard.')}</p><h3>${T('Yayın durumu','Release status')}</h3><p class="fineprint">${T('Bu bir ilk oynanabilir APK sürümüdür; mağaza onayı, cihaz uyumluluğu, içerik derecelendirmesi ve hatasızlık garantisi yoktur. Tarih senaryoları modern sınırlar üzerinde kurgusaldır. Gerçek tarihsel veya siyasi doğruluk iddiası taşımaz.','This is a first playable APK build, without guarantees of store approval, device compatibility, content rating or bug-free operation. Historical-era scenarios are fictional and use modern borders. No historical or political accuracy is claimed.')}</p>`);
 const hs=$$('.modal-content h3');hs[0].textContent='Dictator Era · 0.2.0';
 const privacy=hs.find(h=>h.textContent===T('Gizlilik','Privacy'));
 if(privacy?.nextElementSibling)privacy.nextElementSibling.textContent=T('Misafir modunda veri gönderilmez. Online hesapta komutan adı, profil ülkesi, parola doğrulaması, uygulamaya özgü özetlenmiş cihaz kimliği, sefer kontrol noktaları ve skor Supabase üzerinde işlenir. Parola cihazda saklanmaz; Android oturum anahtarları Keystore ile şifrelenir. E-posta hesabı kullanılmaz; şifre kurtarma koduyla yapılır. Online seferler temel sunucu kontrolleri kullanır, tam hile koruması değildir. Google Play girişi ayrı olarak yapılandırılmamıştır.','Guest mode transmits no data. Online accounts process commander name, profile country, password authentication, app-specific hashed device identity, campaign checkpoints and score on Supabase. Passwords are not stored on the device; Android session credentials are encrypted using Keystore. No email account is used; recovery uses a recovery code. Online campaigns have basic server checks, not full anti-cheat protection. Google Play sign-in is not configured.');
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 if(settings.haptics&&window.Native)Native.haptic();if(!['recruit','declare'].includes(a))sound();
 switch(a){
 case 'guest':guestRegister();break;case 'google':showGoogle();break;case 'online':Online.form();break;
 case 'close':closeDialog();break;case 'menu':showMenu();break;case 'scenarios':showScenarios();break;
 case 'choose-scenario':difficulty=Number($('#difficulty')?.value||1);chooseCountry(id);break;
 case 'select-nation':selected=Number(id);focusCountry(selected);updateSelection();break;
 case 'start':void Online.start(b);break;
 case 'resume':resumeGame();break;case 'settings':showSettings();break;case 'profile':showProfile();break;
 case 'leaderboard':showLeaderboard();break;case 'multiplayer':toast(T('Yakında','Coming soon'));break;
 case 'tutorial':tutorialStep=0;showTutorial();break;case 'tutorial-next':tutorialStep++;showTutorial();break;case 'tutorial-prev':tutorialStep--;showTutorial();break;
 case 'licenses':showLicenses();break;
 case 'zoom-in':zoomAt(camera.z*1.4);break;case 'zoom-out':zoomAt(camera.z/1.4);break;case 'focus':focusCountry(game.player);break;case 'fit':fitWorld();break;
 case 'economy':showEconomy();break;case 'army':unitAmount=Math.max(1,Math.min(unitAmount,Math.floor(me().money/unitDefs[unitType].cost)));showArmy();break;
 case 'unit-type':unitType=Number(id);unitAmount=Math.max(1,Math.min(10,Math.floor(me().money/unitDefs[unitType].cost)));showArmy();break;
 case 'recruit':if(recruit(unitType,unitAmount))showArmy();break;
 case 'technology':showTechnology();break;case 'research':if(research(id))showTechnology();break;
 case 'ideology':showIdeologies();break;case 'ideology-detail':showIdeologyDetail(id);break;case 'reform':if(reform(id))showIdeologies();updateHUDValues();break;
 case 'ranking':showRanking();break;case 'rank-tab':showRanking(id);break;
 case 'diplomacy':showDiplomacy();break;case 'country-diplomacy':showCountryDiplomacy(Number(id));break;
 case 'dip-action':diplomacy(Number(id),b.dataset.kind);showCountryDiplomacy(Number(id));break;
 case 'war-confirm':showWarConfirm(Number(id));break;case 'declare':if(declareWar(game.player,Number(id))){closeDialog();drawCountryPanel();}break;
 case 'call-allies':showCallAllies(id);break;
 case 'ally-request':callAlly(Number(id),Number(b.dataset.war),b.dataset.kind);showCallAllies(b.dataset.war);break;
 case 'peace':peace(Number(id));closeDialog();break;
 case 'newspaper':showNewspaper();break;case 'save':saveGame();break;case 'clear-selection':selected=0;drawCountryPanel();dirty=true;break;
 case 'pause-toggle':game.paused=!game.paused;updateHUDValues();break;case 'pause-menu':showPause();break;
 case 'speed':game.speed=Number(b.dataset.value);game.paused=false;updateHUDValues();break;
 case 'continue':closeDialog();game.paused=false;updateHUDValues();break;
 case 'air-target':closeDialog();game.targetMode='air';selected=0;drawCountryPanel();toast(T('Savaştığın ülkenin hedef bölgesine dokun.','Tap a target region in a nation you are at war with.'));break;
 case 'air-country':closeDialog();game.targetMode='air';focusCountry(Number(id));toast(T('Bombalanacak bölgeye dokun.','Tap the region to strike.'));break;
 case 'nuclear-target':closeDialog();game.targetMode='nuclear';selected=0;drawCountryPanel();toast(T('Önce hedef ülkeyi seç.','First select the target nation.'));break;
 case 'cancel-target':game.targetMode=null;closeDialog();dirty=true;break;
 case 'nuclear-launch':airstrike(Number(id),[Number(b.dataset.x),Number(b.dataset.y)],true);closeDialog();dirty=true;break;
 case 'exit':if(window.Native)Native.exit();else closeDialog();break;
 }
});
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.id==='country-search')filterCountries(el.value);
 if(el.id==='recruit-range'){unitAmount=Number(el.value);$('#recruit-count').textContent=unitAmount;$('#recruit-cost').textContent=num(unitDefs[unitType].cost*unitAmount);}
 if(el.dataset.budget){const k=el.dataset.budget;me()[k]=Number(el.value);$('#budget-'+k).textContent=el.value+'%';updateBudget();}
 if(el.dataset.setting){settings[el.dataset.setting]=el.type==='checkbox'?el.checked:Number(el.value);saveSettings();if(el.dataset.setting==='music'){if(settings.music)musicStart();else $('#music').pause();}if(['admin','flags'].includes(el.dataset.setting))rebuildBase();}
});
document.addEventListener('change',e=>{
 if(e.target.id==='language'){lang=e.target.value;showRegistration();}
 if(e.target.id==='settings-language'){
  lang=e.target.value;profile.lang=lang;store.write('profile',profile);document.documentElement.lang=lang;
  if(mode==='play'){updateHUD();drawCountryPanel();}else if(mode==='menu'){const modal=$('#dialog-layer').innerHTML;showMenu();}
  showSettings();dirty=true;
 }
 if(e.target.id==='quality'){settings.quality=Number(e.target.value);saveSettings();resize();}
});
boot();
